public void upload() {
        log.info("Uploading Chrome user data for user {}", userId);
        if (!needUpload()) {
            log.info("userdata not need to upload, userId:{}", userId);
            return;
        }

        File localUserData = getLocalURL();
        if (!localUserData.exists()) {
            log.warn("browser userdata path is not exist: {}", localUserData);
            return;
        }

        UserdataSlimmer.slimInplace(localUserData);

        File localZip = new File(localUserData.getParent(), "userdata.json.zst");
        try {
            ZstdUtil.compressJson(localUserData.getAbsolutePath(), localZip.getAbsolutePath());
        } catch (Exception e) {
            log.error("Compression failed: {}", localUserData.getAbsolutePath(), e);
            return;
        }

        String remoteURL = getRemoteURL();
        long startUpload = System.currentTimeMillis();
        if (fileStorageService.exist(remoteURL)) {
            fileStorageService.deleteFile(remoteURL);
        }
        fileStorageService.uploadFile(localZip.getAbsolutePath(), remoteURL);
        log.info("upload userdata to remote storage end, cost {} ms", System.currentTimeMillis() - startUpload);

        if (localZip.exists()) {
            FileUtil.del(localZip);
        }
    }

public String download() {
        log.info("Downloading Chrome user data for user {}", userId);
        File localUserData = getLocalURL();
        String remoteURL = getRemoteURL();

        if (!fileStorageService.exist(remoteURL)) {
            log.info("userdata not exist in remote storage, use local path, userId:{}", userId);
            return localUserData.getAbsolutePath();
        }

        if (!localUserData.getParentFile().exists()) {
            FileUtil.mkdir(localUserData.getParentFile());
            FileUtil.touch(localUserData);
        }

        File localZip = new File(localUserData.getParent(), "userdata.json.zst");
        try {
            fileStorageService.downloadFile(localZip.getAbsolutePath(), remoteURL);
            ZstdUtil.decompressJson(localZip.getAbsolutePath(), localUserData.getAbsolutePath());
            if (localZip.exists()) {
                FileUtil.del(localZip);
            }
        } catch (Exception e) {
            log.error("download user data error! userId:{}", userId, e);
        }

        return localUserData.getAbsolutePath();
    }

public void createChrome(byte[] receivedControlPackets, InitBrowserRequest parsedParams, Consumer<Object> consumer) {
        String userId = UserIdUtil.generateUserIdByImeiAndImsi(parsedParams.getImei(), parsedParams.getImsi());
        log.info("create browser instance, userId:{}, parsed params: {}", userId, JSONUtil.toJsonStr(parsedParams));

        ReentrantLock lock = lockManager.getLock(userId);
        try {
            acquireLock(lock, userId);

            UserChrome userChrome = processUserChrome(userId, receivedControlPackets, parsedParams, consumer);
            if (consumer == null || userChrome == null) {
                return;
            }

            loginAndHandleEvent(userChrome, receivedControlPackets, userId, consumer);
            clearAlarms();
        } catch (Exception e) {
            handleCreateChromeException(e, userId);
        } finally {
            releaseLock(lock, userId);
        }
    }

private void processLogin(Client client, Tlv tlv) throws Exception {
        Message message = parseMessage(tlv);
        validateLoginRequest(message);

        String sessionKey = Type.tcpBindKey(message.getImei(), message.getImsi());
        UserBind userBind = validateUserBind(sessionKey, message);

        initializeClientSession(client, message, sessionKey);
        clientSet.set(sessionKey, client);
        loginInfoMap.put(sessionKey, message);

        client.ack(message.getType(), Code.OK);
        chromeSet.updateHeartbeats(sessionKey, System.nanoTime());

        UserBind updatedUserBind = remote.updateUserBind(sessionKey);
        ThreadUtil.execute(() -> createBrowser(client, message, updatedUserBind, tlv));

        recordSessionLogin(sessionKey, message.getAppType(), client.getStr(Client.VAL_TCP_UNIQUE_ID));
    }

private void createBrowser(Client client, Message message, UserBind userBind, Tlv tlv) {
        try {
            String jsonString = JSONUtil.toJsonStr(message);
            InitBrowserRequest request = JSONUtil.toBean(jsonString, InitBrowserRequest.class);
            request.setInnerMediaEndpoint(userBind.getInnerMediaEndpoint());

            byte[] tlvBytes = tlv.marshal(ByteOrder.BIG_ENDIAN);
            remote.createChrome(tlvBytes, request, (future) -> {
                client.send(new LoginResponse(userBind.getMediaEndpoint(), userBind.getMediaTlsEndpoint()));
            });
        } catch (Exception e) {
            client.ack(message.getType(), Code.FAILED);
            log.error("Failed to create browser instance", e);
        }
    }

