public boolean loadSDK(String jarPath) {
        if (StringUtil.isBlank(jarPath)) {
            return true;
        }
        if (muenPluginClassLoader != null) {
            muenPluginClassLoader.close();
        }
        FileUtil.mkdir(config.getJarDirPath());
        FileUtil.clean(config.getJarDirPath());
        FileUtil.copy(jarPath, config.getJarDirPath(), true);

        String name = FileUtil.getName(jarPath);
        String path = FileUtil.file(config.getJarDirPath(), name).getAbsolutePath();
        muenPluginClassLoader = new MuenPluginClassLoader();
        return muenPluginClassLoader.init(Paths.get(path));
    }

public boolean init(Path jarPath) {
        log.info("load jar from {}", jarPath);
        try {
            classLoader = new URLClassLoader(
                    new URL[]{jarPath.toUri().toURL()},
                    Thread.currentThread().getContextClassLoader());
        } catch (MalformedURLException e) {
            log.error("failed to new urlClassLoader", e);
            return false;
        }

        List<String> classNames = listAllClassName(jarPath);
        driverImplClass = findDriverImpl(classNames);
        if (driverImplClass == null) {
            log.warn("cannot find the driver implement class from {}", jarPath);
            return false;
        }
        return true;
    }

public MuenDriver createDriverInstance(HWCallback hwCallback) {
        if (driverImplClass == null || hwCallback == null) {
            return null;
        }
        try {
            return (MuenDriver) driverImplClass.getConstructor(HWCallback.class).newInstance(hwCallback);
        } catch (InstantiationException | IllegalAccessException
                 | InvocationTargetException | NoSuchMethodException e) {
            log.error("failed to instance MuenDriver", e);
            return null;
        }
    }

public void checkBrowsers() {
        Type.HealthCheckResult result = client.browser().healthCheck();
        if (result.isSuccess()) {
            return;
        }
        Set<String> users = chromeSet.getAllUser();
        Set<String> delUsers = new HashSet<>();
        for (String user : users) {
            UserChrome userChrome = chromeSet.get(user);
            String proxyContextId = userChrome.getChromeDriver().getProxyContextId();
            if (result.getErrContexts().contains(proxyContextId)) {
                delUsers.add(user);
            }
        }
        delUsers.forEach(chromeSet::delete);
    }

private void reportChainInfoWithRetry(int maxRetries) {
        for (int remaining = maxRetries; remaining >= 0; remaining--) {
            log.info("start to report chain endpoints");
            if (chromeSet.reportChainEndpoints()) {
                log.info("report chain endpoint success");
                return;
            }
            if (remaining == 0) {
                log.fatal("report chain endpoint failed");
                return;
            }
            log.info("failed to report, will retry");
            try {
                Thread.sleep(RETRY_INTERVAL_MS);
            } catch (InterruptedException e) {
                log.fatal("failed to sleep", e);
                Thread.currentThread().interrupt();
                return;
            }
        }
    }

public void closeExpiredBrowsers() {
        long now = System.nanoTime();
        Set<String> users = chromeSet.getAllUser();
        for (String user : users) {
            long heartbeats = chromeSet.getHeartbeats(user);
            if (now - heartbeats > TIMEOUT_NANOS) {
                chromeSet.delete(user);
            }
        }
    }

